{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시가 청년의 버스·지하철 이용 비용 지원 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시는 청년의 생활안정을 위하여 예산의 범위에서 대중교통수단 이용 비용을 지원할 수 있다. 여기서 대중교통수단은 「대중교통의 육성 및 이용촉진에 관한 법률」 제2조제2호에 따른 대중교통수단을 말하며, 청년은 19세 이상 39세 이하의 사람을 말한다. 다만 그 밖의 관계 법령 및 조례에서 따로 규정하는 경우 그 규정에 따른다.",
          "b_ids": "청년:제15조제3항, 청년:제3조제1호, 청년:제3조제1호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
